<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {Image as ImageIcon,Film,X,ArrowUpRight} from 'lucide-vue-next'
import {mediaFor,type MediaAsset} from '../data/detailContent'
import type {ObjectKind} from '../basketApi'
const props=defineProps<{kind:ObjectKind;id:string;name:string}>()
const all=computed(()=>mediaFor(props.kind,props.id)),photos=computed(()=>all.value.filter(x=>x.kind==='photo')),videos=computed(()=>all.value.filter(x=>x.kind==='video'))
const failed=ref<string[]>([]),active=ref<MediaAsset>(),dialog=ref<HTMLDialogElement>()
function open(m:MediaAsset){active.value=m;dialog.value?.showModal()}
function close(){dialog.value?.close();active.value=undefined}
watch(()=>[props.kind,props.id],()=>{close();failed.value=[]})
</script>
<template><section class="detail-media" :aria-label="name+'媒体资料'"><div class="detail-section-title"><div><span class="tiny-caption">眼见这一程</span><h2>实景图集</h2></div><span class="pending-caption" v-if="!photos.length">待添加</span></div><div class="photo-strip"><template v-if="photos.length"><button v-for="photo in photos" :key="photo.id" type="button" class="detail-photo" :aria-label="'放大查看：'+photo.alt" @click="open(photo)"><img v-if="!failed.includes(photo.id)" :src="photo.src" :alt="photo.alt" loading="lazy" decoding="async" @error="failed.push(photo.id)"><span v-else class="media-slot"><ImageIcon :size="24"/>图片暂不可用</span><small>{{photo.caption}}<ArrowUpRight :size="14"/></small></button></template><div v-else v-for="(label,i) in ['全景','细节','现场']" :key="label" class="media-slot"><ImageIcon :size="22" :stroke-width="1.2"/><span>{{label}}照片</span><small>待添加</small></div></div><div class="detail-section-title video-heading"><h2>影像记</h2><span class="pending-caption" v-if="!videos.length">待添加</span></div><div v-if="!videos.length" class="video-slot"><Film :size="27" :stroke-width="1.2"/><div><strong>{{name}} · 视频</strong><span>视频与封面待添加</span></div></div><figure v-for="video in videos" :key="video.id" class="detail-video"><video v-if="!failed.includes(video.id)" controls playsinline preload="none" :src="video.src" :poster="video.poster" :aria-label="video.alt" @error="failed.push(video.id)"/><p v-else role="status">视频暂不可用</p><figcaption>{{video.caption}} · {{video.source||'来源待添加'}} · {{video.author||'作者待添加'}}</figcaption></figure><dialog ref="dialog" class="media-dialog" @click="($event.target===dialog)&&close()" @close="active=undefined"><button type="button" aria-label="关闭大图" @click="close"><X :size="23"/></button><figure v-if="active"><img :src="active.src" :alt="active.alt"><figcaption>{{active.caption}} · {{active.source||'来源待添加'}} · {{active.author||'作者待添加'}}</figcaption></figure></dialog></section></template>
